ALTER TABLE "transaction_event" ADD CONSTRAINT "fk_transaction_event_buyer_entity_id" FOREIGN KEY ("buyer_entity_id") REFERENCES "entity" ("entity_id") ON DELETE SET NULL;
ALTER TABLE "transaction_event" ADD CONSTRAINT "fk_transaction_event_venue_entity_id" FOREIGN KEY ("venue_entity_id") REFERENCES "entity" ("entity_id") ON DELETE SET NULL;
ALTER TABLE "transaction_event" ADD CONSTRAINT "fk_transaction_event_citation_id" FOREIGN KEY ("citation_id") REFERENCES "citation" ("citation_id") ON DELETE SET NULL;
ALTER TABLE "provenance_event" ADD CONSTRAINT "fk_provenance_event_transaction_entity_id" FOREIGN KEY ("transaction_entity_id") REFERENCES "transaction_event" ("entity_id") ON DELETE SET NULL;
ALTER TABLE "transaction_line" ADD CONSTRAINT "fk_transaction_line_transaction_entity_id" FOREIGN KEY ("transaction_entity_id") REFERENCES "transaction_event" ("entity_id") ON DELETE CASCADE;
ALTER TABLE "transaction_line" ADD CONSTRAINT "fk_transaction_line_subject_entity_id" FOREIGN KEY ("subject_entity_id") REFERENCES "entity" ("entity_id") ON DELETE RESTRICT;
ALTER TABLE "transaction_line" ADD CONSTRAINT "fk_transaction_line_citation_id" FOREIGN KEY ("citation_id") REFERENCES "citation" ("citation_id") ON DELETE SET NULL;
