-- Business/uniqueness constraints
ALTER TABLE "taxonomy_edge" ADD CONSTRAINT "uq_taxonomy_edge" UNIQUE (child_term_id, parent_term_id, edge_type);
ALTER TABLE "taxonomy_label" ADD CONSTRAINT "uq_taxonomy_label" UNIQUE (term_id, label_type, language_tag, label_text);
ALTER TABLE "external_identifier" ADD CONSTRAINT "uq_external_identifier" UNIQUE (scheme_code, identifier_value);
ALTER TABLE "assertion" ADD CONSTRAINT "ck_assertion_value" CHECK (((value_kind='entity') AND object_entity_id IS NOT NULL) OR ((value_kind='text') AND value_text IS NOT NULL) OR ((value_kind='number') AND value_number IS NOT NULL) OR ((value_kind='date') AND value_date IS NOT NULL) OR ((value_kind='boolean') AND value_boolean IS NOT NULL) OR ((value_kind='json') AND value_json IS NOT NULL));
ALTER TABLE "menu_section" ADD CONSTRAINT "uq_menu_section_sequence" UNIQUE (menu_entity_id, sequence);
ALTER TABLE "menu_item" ADD CONSTRAINT "uq_menu_item_sequence" UNIQUE (menu_entity_id, sequence);
ALTER TABLE "manifestation_expression" ADD CONSTRAINT "uq_manifestation_expression" UNIQUE (manifestation_entity_id, expression_entity_id);
ALTER TABLE "collection_membership" ADD CONSTRAINT "uq_collection_member" UNIQUE (collection_entity_id, member_entity_id, membership_role);
CREATE UNIQUE INDEX "uq_current_holding" ON "holding" (item_entity_id) WHERE is_current = true;
CREATE UNIQUE INDEX "uq_digital_resource_sha256" ON "digital_resource" (sha256) WHERE sha256 IS NOT NULL;
ALTER TABLE "menu_item" ADD CONSTRAINT "ck_menu_item_transcription_confidence" CHECK (transcription_confidence IS NULL OR (transcription_confidence >= 0 AND transcription_confidence <= 1));
ALTER TABLE "transcription" ADD CONSTRAINT "ck_transcription_overall_confidence" CHECK (overall_confidence IS NULL OR (overall_confidence >= 0 AND overall_confidence <= 1));
